// ─── Helpers ─────────────────────────────────────────────────────

/** Look up a script by its canonical ID */
export function getScriptById(id: string): ScriptEntry | undefined {
  return SCRIPTS_REGISTRY.find((s) => s.id === id)
}

/** All scripts belonging to a given module */
export function getScriptsByModule(moduleId: string): ScriptEntry[] {
  return SCRIPTS_REGISTRY.filter((s) => s.moduleId === moduleId)
}

/** All scripts of a given type */
export function getScriptsByType(type: ScriptType): ScriptEntry[] {
  return SCRIPTS_REGISTRY.filter((s) => s.type === type)
}

/** All objection-response scripts (the 7 named objections) */
export function getObjectionScripts(): ScriptEntry[] {
  return SCRIPTS_REGISTRY.filter((s) => s.type === 'objection-response')
}

/** Unique module IDs present in the registry */
export function getModuleIds(): string[] {
  return [...new Set(SCRIPTS_REGISTRY.map((s) => s.moduleId))]
}

/** Count of scripts per module */
export function getModuleScriptCounts(): Record<string, number> {
  const counts: Record<string, number> = {}
  for (const s of SCRIPTS_REGISTRY) {
    counts[s.moduleId] = (counts[s.moduleId] || 0) + 1
  }
  return counts
}
